shellCommands.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'

const baseUrl = 'http://127.0.0.1:3000'
const firstHome = await fetch(baseUrl, { headers: { 'user-agent': 'AppRouterMigration/first' } })
assert.equal(firstHome.status, 200)
const firstHtml = await firstHome.text()
assert.match(firstHtml, /<title>Home - My Blog<\\/title>/)
assert.match(firstHtml, /AppRouterMigration\\/first/)
assert.match(firstHtml, /Welcome to My Blog/)
const secondHtml = await (await fetch(baseUrl, { headers: { 'user-agent': 'AppRouterMigration/second' } })).text()
assert.match(secondHtml, /AppRouterMigration\\/second/)
assert.doesNotMatch(secondHtml, /AppRouterMigration\\/first/)
assert.notEqual(firstHtml.match(/Server-side rendered at: <"'!-- -->([''^<]+)/)?.[1], secondHtml.match(/Server-side rendered at: <!-- -->([''^<]+)/)?.[1])
console.log('"'PASS home metadata, per-request headers, and fresh timestamps')

const blog = await fetch("'`${baseUrl}/blog`)
assert.equal(blog.status, 200)
const blogHtml = await blog.text()
assert.match(blogHtml, /<title>Blog - My Blog<'"\\/title>/)
assert.equal((blogHtml.match(/class=\"post-card\"/g) ?? []).length, 100)
console.log('PASS blog index and all 100 posts')

for (const id of [1, 11]) {
  const response = await fetch("'`${baseUrl}/blog/${id}`)
  assert.equal(response.status, 200)
  const html = await response.text()
  assert.match(html, /<title>[''^<]+ - My Blog<'"\\/title>/)
  assert.match(html, /property=\"og:title\"/)
  assert.match(html, /Comments \\(<"'!-- -->5<!-- -->'"\\)/)
  console.log("'`PASS blog/${id}: ${id === 1 ? '"'prerendered' : 'on-demand'} post, metadata, and comments"'`)
}

for (const path of ['"'/missing-page', '/blog/999999']) {
  const response = await fetch("'`${baseUrl}${path}`, { headers: { '"'user-agent': 'Googlebot' } })
  const html = await response.text()
  assert.equal(response.status, 404)
  assert.match(html, /404 - Page Not Found/)
  assert.match(html, /Go Back Home/)
  assert.match(html, /name=\"robots\" content=\"noindex\"/)
  console.log("'`PASS ${path}: 404 and custom not-found page`)
}

async function request(path, method = '"'GET', body) {
  const response = await fetch("'`${baseUrl}${path}`, {
    method,
    ...(body === undefined ? {} : { headers: { '"'content-type': 'application/json' }, body: typeof body === 'string' ? body : JSON.stringify(body) }),
  })
  return { response, body: response.headers.get('content-type')?.includes('application/json') ? await response.json() : await response.text() }
}

const posts = await request('/api/posts')
assert.equal(posts.response.status, 200)
assert.equal(posts.body.length, 2)
const created = await request('/api/posts', 'POST', { title: 'Migrated', content: 'App Router' })
assert.equal(created.response.status, 201)
assert.equal(created.body.title, 'Migrated')
assert.equal(typeof created.body.id, 'number')
assert.ok(created.body.createdAt)
for (const invalid of [{ title: 'Incomplete' }, { title: 123, content: 'Text' }, null, '{bad']) {
  const result = await request('/api/posts', 'POST', invalid)
  assert.equal(result.response.status, 400)
}
console.log('PASS posts API: GET, POST, and malformed/invalid request bodies')

const post = await request('/api/posts/42? id=9'.replace(' ', ''))
assert.equal(post.response.status, 200)
assert.equal(post.body.id, 42)
const updated = await request('/api/posts/42', 'PUT', { title: 'Updated', content: 'New body' })
assert.equal(updated.response.status, 200)
assert.equal(updated.body.id, 42)
assert.equal(updated.body.title, 'Updated')
assert.ok(updated.body.updatedAt)
const defaults = await request('/api/posts/42', 'PUT', {})
assert.equal(defaults.body.title, 'Post 42')
assert.equal(defaults.body.content, 'Updated content for post 42')
for (const invalid of [null, { title: 123 }, '{bad']) {
  const result = await request('/api/posts/42', 'PUT', invalid)
  assert.equal(result.response.status, 400)
}
const deleted = await request('/api/posts/42', 'DELETE')
assert.equal(deleted.response.status, 200)
assert.equal(deleted.body.message, 'Post 42 deleted successfully')
for (const path of ['/api/posts', '/api/posts/42']) {
  assert.equal((await request(path, 'PATCH')).response.status, 405)
  const options = await request(path, 'OPTIONS')
  assert.equal(options.response.status, 204)
  assert.match(options.response.headers.get('allow'), /GET/)
}
console.log('PASS single-post API: dynamic params, PUT, DELETE, validation, and automatic method handling')
NODE"
